# F4: does the leak-forecast uncertainty change the MPC decision?
#
# Uses the MC-dropout ensemble regenerated by python/f4_leak_ensemble.py
# (results/f4_risk/leak_ensemble_<t_q>.mat, 1000 trajectories of the BiLSTM with
# models/model_200x200_drop1_1.pth) on the ROM query of F1/F2, with the archived
# actuator bounds and the P0 cost (soft ramp). For other actuator limits see
# f4_actuator_sweep.jl.
#
# Decisions compared (all on the nonlinear N3 model, implicit Euler as in F2):
#   D(q)   deterministic NLP with the leak at the ensemble percentile q (5, 50, 95),
#          with the dropout-free forecast, and with the realized leak (oracle) when known
#   SAA    two-stage SAA on M = 59 members (as the loop's N_par): ṁ₀ shared, ṁ₁…ṁ_{K−1}
#          per scenario (recourse), mean P0 cost; the structure assumed in §7.1
# Out-of-sample evaluation: open-loop sequences re-simulated (ode1be) on all held-out
# members, and the two-stage value of each first action ṁ₀ (recourse re-optimized).
#
# Usage, from the repository root:  julia --project=julia julia/f4_risk_decisions.jl [t_q] [M] [n_oos]
include(joinpath(@__DIR__, "F4Lib.jl"))
using .F4Lib, Printf, Statistics, Random

TQ = length(ARGS) >= 1 ? ARGS[1] : "1180"
M_SAA = length(ARGS) >= 2 ? parse(Int, ARGS[2]) : 59
N_OOS = length(ARGS) >= 3 ? parse(Int, ARGS[3]) : 100
c = load_query(TQ)
K, h, Y, NENS = c.K, c.h, c.Y, c.NENS

# --- spread of the forecast and its effect on the PCT, before any optimization
dM = vec(sum(Y, dims = 2)) * h
@printf("t_q = %.1f s: %d members; leak sd step 1 / %d: %.3f / %.3f kg/s; integrated-leak sd over the horizon %.3f kg\n",
        c.t_q, NENS, K - 1, std(Y[:, 1]), std(Y[:, end]), std(dM))
@printf("F3 sensitivity ∂ŷ/∂ΔM ≈ −1.6e-2 K/kg → forecast spread ≈ %.4f K of PCT at the end of the horizon\n",
        1.6e-2 * std(dM))
c.real_leak === nothing || @printf("realized integrated leak − ensemble median: %+.3f kg (z = %+.2f)\n",
        sum(c.real_leak[2:end]) * h - median(dM), (sum(c.real_leak[2:end]) * h - median(dM)) / std(dM))

# --- decisions
solve_det(c, quantile_leak(c, 50))                        # compile
cands = Pair{String,Vector{Float64}}["p05" => quantile_leak(c, 5), "p50" => quantile_leak(c, 50),
                                     "p95" => quantile_leak(c, 95), "no dropout" => c.det_leak,
                                     "F2 leak" => c.used_leak]
c.real_leak === nothing || push!(cands, "realized (oracle)" => c.real_leak)
dec = Dict{String,Any}()
println("\ndecision            status            time [s]   ṁ₀ [kg/s]   u₀ [A]     J (own scenario)")
for (name, L) in cands
    s = solve_det(c, L)
    dec[name] = s.m
    @printf("%-19s %-17s %7.2f    %8.4f    %.5f   %.6f\n", name, string(s.status), s.time, s.m[1],
            massflow_to_current(s.m[1]), s.obj)
end
Random.seed!(1)
perm = randperm(NENS); ins = perm[1:M_SAA]; oos = perm[M_SAA+1:end]
saa = solve_saa(c, [scen(c, i) for i in ins]; guess = dec["p50"])
dec["SAA (2-stage)"] = saa.m[1]
@printf("%-19s %-17s %7.2f    %8.4f    %.5f   %.6f  (mean over %d in-sample)\n", "SAA (2-stage)",
        string(saa.status), saa.time, saa.m0, massflow_to_current(saa.m0), saa.obj, M_SAA)

# --- out of sample: open-loop sequences on all held-out members (+ realized)
names = [first.(cands); "SAA (2-stage)"]
println("\nopen-loop re-simulation on $(length(oos)) held-out members (ode1be):")
println("decision              mean J      p95 J      CVaR95 J   max PCT p99 [K]   J on realized")
for n in names
    J = Float64[]; Ymax = Float64[]
    for i in oos
        ev = evaluate(c, dec[n], scen(c, i)); push!(J, ev.J); push!(Ymax, maximum(ev.y))
    end
    tail = sort(J)[ceil(Int, 0.95 * length(J)):end]
    jr = c.real_leak === nothing ? NaN : evaluate(c, dec[n], c.real_leak).J
    @printf("%-19s  %9.5f  %9.5f  %9.5f   %10.4f        %9.5f\n", n, mean(J), quantile(J, 0.95), mean(tail),
            quantile(Ymax, 0.99), jr)
end

# --- two-stage value of the first action (recourse re-optimized per held-out member)
sub = oos[1:min(N_OOS, length(oos))]
println("\ntwo-stage value of ṁ₀ on $(length(sub)) held-out members (recourse re-optimized):")
m0s = unique(round.([dec[n][1] for n in names]; digits = 6))
for m0 in m0s
    v = solve_saa(c, [scen(c, i) for i in sub]; m0_fixed = m0, guess = dec["p50"])
    who = join([n for n in names if round(dec[n][1]; digits = 6) == m0], ", ")
    @printf("ṁ₀ = %8.4f kg/s (%s): mean J = %.6f  [%s, %.1f s]\n", m0, who, v.obj, string(v.status), v.time)
end

open(joinpath(@__DIR__, "..", "results", "f4_risk", "f4_decisions_$TQ.csv"), "w") do io
    println(io, "t," * join(replace.(names, r"[ ()-]" => ""), ","))
    for k in 1:K
        println(io, join([@sprintf("%.1f", c.tX[c.hor[k]]); [@sprintf("%.8f", dec[n][k]) for n in names]], ","))
    end
end
